import { t, translateError } from './i18n.mjs';
import {savedPreviewsKey} from './saved-model.mjs';
import {showSupportChoices,showSupportMessageStep} from './card-actions.mjs';
import {debtCardHTML,cardDetailsHTML} from './debt-card.mjs';
let previewSkipped=false,previewSaved=false;let draftCardId=crypto.randomUUID();
import {defaultPrivacy,validateDetails,publicCard} from './card-model.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let api,identity={},step=1,debts=[{title:'',story:'',amount:''}],privacy=defaultPrivacy(),submitted=false;
const options=()=>[['realName',t("Show my real name","Hiển thị họ tên thật","실명 표시"),t("Show your full name on the card.","Hiển thị họ tên thật trên thẻ.","카드에 실명을 표시합니다.")],['age',t("Show my age","Hiển thị tuổi","나이 표시"),t("Show your age if you’ve provided it.","Hiển thị tuổi của bạn nếu đã cung cấp.","입력한 나이를 표시합니다.")],['location',t("Show my location","Hiển thị địa điểm","지역 표시"),t("Show your location if you’ve provided it.","Hiển thị địa điểm nếu bạn đã cung cấp.","입력한 지역을 표시합니다.")],['photo',t("Show my profile photo","Hiển thị ảnh đại diện","프로필 사진 표시"),t("Show your profile picture if you’ve added one.","Hiển thị ảnh đại diện nếu đã có.","등록한 프로필 사진을 표시합니다.")],['publicStory',t("Show my story to the public","Công khai câu chuyện của tôi","내 이야기 공개"),t("Let your story appear on the public card.","Cho phép câu chuyện của bạn xuất hiện trên bản xem công khai.","공개 카드에 이야기를 표시합니다.")]];
export function initCardWizard(callbacks){api=callbacks;const root=document.createElement('section');root.id='card-wizard';document.body.append(root);root.addEventListener('input',event=>{const field=event.target;if(field.dataset.field)debts[Number(field.dataset.index)][field.dataset.field]=field.dataset.field==='amount'?(field.value===''?'':Number(field.value)):field.value;});root.addEventListener('change',event=>{if(event.target.dataset.privacy){privacy[event.target.dataset.privacy]=event.target.checked;const label=event.target.closest('.cw-switch').querySelector('.cw-switch-state');label.textContent=event.target.checked?t("On","Bật","켜짐"):t("Off","Tắt","꺼짐");}});root.addEventListener('click',event=>{const b=event.target.closest('[data-cw]');if(!b||submitting)return;switch(b.dataset.cw){case 'restore-card':previewSkipped=false;render();break;case 'back':if(submitted){document.body.classList.remove('card-wizard-mode');api.profile();return;}else if(step>1)step--;else{document.body.classList.remove('card-wizard-mode');api.back();return;}render();break;case 'next':if(step===1){try{debts=validateDetails(debts);}catch(error){errorMessage(error.message);return;}}step=Math.min(3,step+1);render();break;case 'add':if(debts.length>=20){errorMessage(t("You can add up to 20 debts.","Bạn có thể thêm tối đa 20 khoản nợ.","채무는 최대 20개까지 추가할 수 있습니다."));return;}debts.push({title:'',story:'',amount:''});render();document.querySelector(`[data-index="${debts.length-1}"]`)?.focus();break;case 'remove':debts.splice(Number(b.dataset.index),1);render();break;case 'step':{const target=Number(b.dataset.step);if(!submitted&&target<step){step=target;render();}break;}case 'submit':submit();break;case 'new':previewSaved=false;previewSkipped=false;draftCardId=crypto.randomUUID();debts=[{title:'',story:'',amount:''}];privacy=defaultPrivacy();step=1;submitted=false;render();break;case 'profile':document.body.classList.remove('card-wizard-mode');api.profile();break;case 'debts':document.body.classList.remove('card-wizard-mode');api.debts();break;}});}
export function showCardWizard(user){identity={...user,nickname:user?.nickname||(user?.designPreview?'Broke_Studio':'Broke_'+(user?.id||'preview').slice(0,6))};previewSkipped=false;document.body.classList.remove('onboarding','registration-mode','broke-mode','debts-mode','messages-mode','bros-join-mode');document.body.classList.add('card-wizard-mode');render();window.scrollTo(0,0);}
function errorMessage(message){const field=document.querySelector('#cw-error');if(field){field.textContent=translateError(message);field.focus();}}
function render(){const root=document.querySelector('#card-wizard');root.innerHTML=`<div class="cw-shell"><div class="cw-header"><img src="assets/debtfreelately-logo-transparent.png" alt="DebtFreeLately"><a href="/my-cards" class="cw-status-link">${t("Submitted cards","Thẻ đã gửi","제출한 카드")}</a><button data-cw="${step===1&&!submitted?'profile':'back'}">← ${step===1&&!submitted?t("Profile","Trang cá nhân","프로필"):t("Back","Quay lại","뒤로")}</button></div><div class="cw-intro"><span>${t("YOUR NEXT CHAPTER STARTS HERE","CHƯƠNG MỚI CỦA BẠN BẮT ĐẦU TỪ ĐÂY","여기서 새로운 시작을")}</span><h1>${t("Create Your Debt Card","Tạo thẻ báo nợ","채무 카드 만들기")}</h1><p>${t("An honest story. A chance to move forward together.","Một câu chuyện chân thành. Một cơ hội để cùng nhau bước tiếp.","진솔한 이야기로 함께 앞으로 나아갈 기회.")}</p></div><ol class="cw-progress" aria-label="${t("Card creation steps","Các bước tạo thẻ","카드 만들기 단계")}">${[t("Details","Chi tiết","상세 정보"),t("Privacy","Quyền riêng tư","공개 범위"),t("Review Card","Xem lại thẻ","카드 검토")].map((label,index)=>`<li class="${step===index+1&&!submitted?'current':step>index+1||submitted?'complete':''}" ${step===index+1&&!submitted?'aria-current="step"':''}><button data-cw="step" data-step="${index+1}" ${submitted||index+1>=step?'disabled':''}><b>${step>index+1||submitted?'✓':index+1}</b><span>${label}</span></button></li>`).join('')}</ol><div class="cw-content">${submitted?successView():step===1?detailsView():step===2?privacyView():reviewView()}</div>${submitted?'':`<div id="cw-error" class="cw-error" tabindex="-1" role="alert"></div><div class="cw-navigation"><button class="cw-back" data-cw="back">← ${step===1?t("Back","Quay lại","뒤로"):t("Previous step","Bước trước","이전 단계")}</button><span>${t("Step","Bước","단계")} ${step} / 3</span><button class="cw-next" data-cw="${step===3?'submit':'next'}">${step===3?t("Submit","Gửi thẻ","제출"):t("Continue","Tiếp tục","계속")} <span>→</span></button></div>`}<p class="cw-storage">${t("Submitted cards are sent to the admin for review. Unsubmitted content is kept for this session only.","Thẻ đã gửi sẽ được admin xét duyệt. Nội dung chưa gửi chỉ được giữ trong phiên này.","제출한 카드는 관리자가 검토합니다. 제출하지 않은 내용은 이번 세션에만 유지됩니다.")}</p></div>`;}
function detailsView(){return `<div class="cw-section-heading"><h2>${t("Debt Details","Chi tiết khoản nợ","채무 상세 정보")}</h2><p>${t("Select + below to add more debts.","Bạn có thể thêm nhiều hơn một khoản nợ bằng cách chọn dấu + bên dưới.","아래 +를 선택해 채무를 더 추가할 수 있습니다.")}</p></div><div class="cw-debt-groups">${debts.map((debt,index)=>`<section class="cw-debt-group"><div class="cw-group-header"><span>${t("DEBT","KHOẢN NỢ","채무")} ${String(index+1).padStart(2,'0')}</span>${debts.length>1?`<button data-cw="remove" data-index="${index}" aria-label="${t(`Remove debt ${index+1}`,`Xóa khoản nợ ${index+1}`,`채무 ${index+1} 삭제`)}">×</button>`:''}</div><label for="cw-title-${index}">${t("Title","Tiêu đề","제목")} <span>*</span></label><p class="cw-field-help">${t("A short title for this debt, displayed on your card.","Tiêu đề tóm tắt khoản nợ của bạn, hiển thị trên thẻ.","카드에 표시되는 채무의 짧은 제목입니다.")}</p><input id="cw-title-${index}" data-field="title" data-index="${index}" maxlength="100" required placeholder="${t("Example: A little breathing room to finish my final year","Ví dụ: Một khoảng thở để hoàn thành năm học cuối","예: 마지막 학년을 마치기 위한 작은 여유")}" value="${esc(debt.title)}"><label for="cw-amount-${index}">${t("Debt amount (VND)","Số tiền nợ (VNĐ)","채무 금액(VND)")} <span>*</span></label><p class="cw-field-help">${t("The amount you still owe on this debt.","Số tiền hiện còn nợ của khoản này.","이 채무의 남은 금액입니다.")}</p><input id="cw-amount-${index}" data-field="amount" data-index="${index}" type="number" inputmode="numeric" min="1" max="1000000000000" step="1" required placeholder="${t("Example: 14000000","Ví dụ: 14000000","예: 14000000")}" value="${esc(debt.amount)}"><label for="cw-story-${index}">${t("Your story","Câu chuyện của bạn","내 이야기")} <span>*</span></label><p class="cw-field-help">${t("How did this debt come about? Help Bros understand your story.","Vì sao bạn có khoản nợ này? Chia sẻ để Bros hiểu hơn về câu chuyện của bạn.","이 채무는 어떻게 생겼나요? Bros가 이해할 수 있도록 이야기를 들려주세요.")}</p><textarea id="cw-story-${index}" data-field="story" data-index="${index}" maxlength="3000" required placeholder="${t("Tell your story in your own words…","Hãy kể câu chuyện của bạn bằng lời của chính mình…","자신의 말로 이야기를 들려주세요…")}">${esc(debt.story)}</textarea><small>${t("Up to 3,000 characters. Leave out card numbers, account numbers and personal documents.","Tối đa 3.000 ký tự. Tránh ghi thông tin thẻ, số tài khoản hoặc giấy tờ cá nhân.","최대 3,000자. 카드 번호, 계좌번호, 개인 서류는 포함하지 마세요.")}</small></section>`).join('')}</div><button class="cw-add" data-cw="add" ${debts.length>=20?'disabled':''}><b>＋</b> ${t("Add debt","Thêm khoản nợ","채무 추가")}</button>`;}
function privacyView(){return `<div class="cw-section-heading"><h2>${t("Privacy & Display","Quyền riêng tư &amp; hiển thị","공개 범위 설정")}</h2><p>${t("Choose what other people can see on your card.","Bạn quyết định những gì người khác nhìn thấy trên thẻ của mình.","다른 사람에게 카드의 어떤 정보를 보여줄지 선택하세요.")}</p></div><div class="cw-privacy-list">${options().map(([key,label,description])=>`<div class="cw-privacy-row"><div><label for="cw-privacy-${key}">${label}</label><p>${description}</p></div><label class="cw-switch"><input id="cw-privacy-${key}" type="checkbox" role="switch" data-privacy="${key}" ${privacy[key]?'checked':''}><span class="cw-switch-track"></span><span class="cw-switch-state">${privacy[key]?t("On","Bật","켜짐"):t("Off","Tắt","꺼짐")}</span></label></div>`).join('')}</div><div class="cw-privacy-note">${t("♧ These settings are off by default. If you haven’t provided your age, location or profile photo, the card leaves them blank.","♧ Các mục mặc định ở trạng thái tắt. Nếu chưa có tuổi, địa điểm hoặc ảnh đại diện, thẻ sẽ để trống các mục đó.","♧ 기본값은 꺼짐입니다. 나이, 지역 또는 프로필 사진을 제공하지 않으면 해당 정보는 비워 둡니다.")}</div>`;}
function preview(){try{previewSaved=Boolean(JSON.parse(localStorage.getItem(savedPreviewsKey(identity.id||'device-preview'))||'{}')[draftCardId]);}catch{}const card=publicCard(debts,privacy,identity);return previewSkipped?'<div class="df-skipped"><h3>'+t("Card preview skipped.","Đã bỏ qua thẻ xem trước.","카드 미리보기를 건너뛰었습니다.")+'</h3><p>'+t("Your card content is still available.","Thao tác này không xóa nội dung thẻ của bạn.","카드 내용은 그대로 유지됩니다.")+'</p><button data-cw="restore-card">'+t("↶ View card again","↶ Xem lại thẻ","↶ 카드 다시 보기")+'</button></div>':debtCardHTML(card,{saved:previewSaved,id:draftCardId});}
function reviewView(){return `<div class="cw-section-heading"><h2>${t("Review Card","Xem lại thẻ","카드 검토")}</h2><p>${t("This is how your card will look to Bros with your current privacy settings.","Đây là bản xem trước nội dung Bros sẽ thấy, theo các lựa chọn riêng tư của bạn.","현재 공개 범위 설정에 따라 Bros에게 보이는 카드입니다.")}</p></div><div class="cw-review-layout">${preview()}<aside class="cw-review-note"><span>♧</span><h3>${t("Your story. Your choice.","Câu chuyện của bạn. Lựa chọn của bạn.","내 이야기는 내가 정합니다.")}</h3><p>${t("Check the title, story and visible details before submitting.","Kiểm tra lại tiêu đề, câu chuyện và thông tin hiển thị trước khi gửi thẻ.","제출하기 전에 제목, 이야기와 공개 정보를 확인하세요.")}</p><p>${t("You’ve added","Bạn đã thêm","추가한 채무:")} <strong>${debts.length} ${t("debts","khoản nợ","건")}</strong>.</p><button data-cw="back">${t("Edit privacy settings ←","Chỉnh lại quyền riêng tư ←","공개 범위 수정 ←")}</button></aside></div>`;}
let submitting=false;
async function submit(){if(submitting)return;try{debts=validateDetails(debts);submitting=true;const button=document.querySelector('[data-cw="submit"]');if(button){button.disabled=true;button.textContent=t("Submitting…","Đang gửi…","제출 중…");}const response=await fetch('/api/cards',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({submissionId:draftCardId,debts,privacy})});const result=await response.json();if(!response.ok)throw Error(result.error||t("Could not submit the card.","Không thể gửi thẻ.","카드를 제출할 수 없습니다."));submitted=true;render();document.querySelector('#cw-success-title')?.focus();}catch(error){errorMessage(error.message||t("Could not submit the card. Your content has been kept.","Không thể gửi thẻ. Nội dung của bạn vẫn được giữ lại.","카드를 제출할 수 없습니다. 입력한 내용은 유지됩니다."));const button=document.querySelector('[data-cw="submit"]');if(button){button.disabled=false;button.textContent=t("Submit →","Gửi thẻ →","제출 →");}}finally{submitting=false;}}
function successView(){return `<div class="cw-success"><div class="cw-success-check">✓</div><h2 id="cw-success-title" tabindex="-1">${t("Submitted successfully","Gửi thẻ thành công","제출 완료")}</h2><p>${t("Your debt card was sent to the admin and is pending review.","Thẻ báo nợ đã được gửi đến admin và đang chờ duyệt.","채무 카드가 관리자에게 전달되어 심사 대기 중입니다.")}<br>${t("Your card will appear in the swipe feed after approval.","Chỉ sau khi được duyệt, thẻ mới xuất hiện trong trang quẹt.","승인되면 스와이프 목록에 카드가 표시됩니다.")}</p><div class="cw-success-actions"><a class="cw-next" href="/my-cards">${t("View card status","Xem trạng thái thẻ","카드 상태 보기")}</a><button class="cw-next" data-cw="profile">${t("Back to profile →","Về trang cá nhân →","프로필로 돌아가기 →")}</button><button class="cw-back" data-cw="new">${t("＋ Create another card","＋ Tạo thẻ mới","＋ 새 카드 만들기")}</button></div></div><div class="cw-success-preview">${preview()}</div>`;}
document.addEventListener('click',event=>{const button=event.target.closest('#card-wizard [data-dc]');if(!button)return;const card=publicCard(debts,privacy,identity);if(button.dataset.dc==='skip'){previewSkipped=true;render();}if(button.dataset.dc==='detail')showSupportChoices({modal:api.modal,close:api.close,pay:()=>showSupportMessageStep({id:'preview:'+draftCardId,name:card.name,modal:api.modal,toast:api.toast}),contact:()=>api.contact({id:'preview:'+draftCardId,name:card.name,title:card.debts.map(d=>d.title).join(' · ')})});if(button.dataset.dc==='save'){try{const key=savedPreviewsKey(identity.id||'device-preview'),saved=JSON.parse(localStorage.getItem(key)||'{}');if(previewSaved)delete saved[draftCardId];else saved[draftCardId]=card;localStorage.setItem(key,JSON.stringify(saved));previewSaved=!previewSaved;render();api.toast(previewSaved?t("Card preview saved on this device.","Đã lưu thẻ xem trước trên thiết bị.","이 기기에 카드 미리보기를 저장했습니다."):t("Card preview removed from saved cards.","Đã bỏ lưu thẻ xem trước.","카드 미리보기 저장을 취소했습니다."));}catch{api.toast(t("Could not save the card on this device.","Không thể lưu thẻ trên thiết bị.","이 기기에 카드를 저장할 수 없습니다."));}}});


export function startNewDebtCard(user){debts=[{title:'',story:'',amount:''}];privacy=defaultPrivacy();step=1;submitted=false;previewSkipped=false;previewSaved=false;draftCardId=crypto.randomUUID();showCardWizard(user);}


